parameters.jsonBody:
={{ JSON.stringify({
  "text": "🚨 [FAILURE ALERT] n8n Workflow Error: " + ($json.workflow.name || "Unknown Workflow"),
  "blocks": [
    {
      "type": "header",
      "text": {
        "type": "plain_text",
        "text": "🚨 n8n Workflow Execution Failed",
        "emoji": true
      }
    },
    {
      "type": "section",
      "fields": [
        {
          "type": "mrkdwn",
          "text": "*🔄 Workflow:* " + ($json.workflow.name || "Unknown Workflow")
        },
        {
          "type": "mrkdwn",
          "text": "*❌ Failed Node:* `" + (($json.execution.error && $json.execution.error.node && $json.execution.error.node.name) || $json.execution.lastNodeExecuted || "Unknown Node") + "`"
        }
      ]
    },
    {
      "type": "divider"
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*⚠️ Error Details:*\n```" + (($json.execution.error && $json.execution.error.message) || "An unexpected error occurred during execution.") + "```\n\n*🔗 Execution ID:* `" + $json.execution.id + "`"
      }
    },
    {
      "type": "actions",
      "elements": [
        {
          "type": "button",
          "text": {
            "type": "plain_text",
            "text": "🔍 View Execution in n8n",
            "emoji": true
          },
          "url": "https://n8n-fggh.onrender.com/workflow/" + $json.workflow.id + "/executions/" + $json.execution.id,
          "style": "danger"
        }
      ]
    }
  ]
}) }}
